export function parseJob(input) {
  const job = JSON.parse(input);
  if (typeof job.id !== "string" || !job.id.trim()) throw new Error("Job id required");
  return { id: job.id.trim(), payload: job.payload };
}

import { parseJob } from "../../core/src/index.js";
export async function runJob(input, handler) {
  const job = parseJob(input);
  const result = await handler(job.payload);
  return { id: job.id, result };
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { runJob } from "../packages/worker/src/index.js";
test("passes payload and retains identity", async () => assert.deepEqual(await runJob(JSON.stringify({id:"  j1  ",payload:2}), async x => x*2), {id:"j1",result:4}));
test("propagates handler failure", async () => assert.rejects(runJob(JSON.stringify({id:"j1"}), async () => {throw new Error("failed");}), /failed/));

export function createCache(ttl = 5000, now = Date.now) {
  const values = new Map();
  return {
    getOrSet(key, make) {
      const entry = values.get(key);
      if (entry && entry.until > now()) return entry.value;
      const value = make();
      values.set(key, {value, until:now()+ttl});
      return value;
    },
    size() { return values.size; },
    clear() { values.clear(); }
  };
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { createCache } from "../src/cache.js";
test("expires at the TTL boundary", () => {let clock=0; const cache=createCache(5000,()=>clock); assert.equal(cache.getOrSet("a",()=>1),1); clock=4999; assert.equal(cache.getOrSet("a",()=>2),1); clock=5000; assert.equal(cache.getOrSet("a",()=>3),3);});
test("size includes expired entries until clear", () => {let clock=0; const cache=createCache(5000,()=>clock); cache.getOrSet("a",()=>1); clock=5000; assert.equal(cache.size(),1); cache.clear(); assert.equal(cache.size(),0);});
